      "id": "task-3",
      "title": "Summarize key events and issues",
      "description": "Extract and summarize the main events from the log, highlighting any critical issues, warnings, and important user activities"
    },
    {
      "id": "task-4",
      "title": "Prepare short report",
      "description": "Create a concise report summarizing the log analysis findings, including key events, issues identified, and any recommendations for attention"
